import sys; sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/deps')
import zstandard as zstd, io
from classify_responses import complete_frames
p=zstd.ZstdCompressionParameters(window_log=27)
blob=zstd.ZstdCompressor(compression_params=p).compress(b'abc'*100)
print('wl27 window', zstd.get_frame_parameters(blob).window_size)
try: complete_frames(blob); print('accepted 128MiB window')
except Exception as e: print('REJECTED128',e)
try:
  q=zstd.ZstdCompressionParameters(window_log=28)
  blob2=zstd.ZstdCompressor(compression_params=q).compress(b'abc'*100)
  print('wl28 window', zstd.get_frame_parameters(blob2).window_size)
  try: complete_frames(blob2); print('MISSED big window')
  except Exception as e: print('rejected big window:',e)
  try:
     print(len(zstd.ZstdDecompressor(max_window_size=128*1024**2).stream_reader(io.BytesIO(blob2),read_across_frames=True).read()))
     print('library accepted big window (unexpected)')
  except Exception as e: print('library rejects big window:',type(e).__name__,e)
except Exception as e: print('no wl28', e)
# unused bit
def raw_frame(payload, desc_extra=0):
    out=bytearray((0xfd2fb528).to_bytes(4,'little')); out+=bytes([0x20|desc_extra, len(payload)&0xff])
    out+=((0)|(0<<1)|(len(payload)<<3)|(1<<0)).to_bytes(3,'little'); out+=payload
    return bytes(out)
b=raw_frame(b'hello',0x10); complete_frames(b); print('unused bit ignored ok', zstd.ZstdDecompressor().stream_reader(io.BytesIO(b),read_across_frames=True).read())
